/bin/bash -c "python3 - <<'PY'
from pathlib import Path
import re,statistics
rows=[]
for line in Path('tmp/pdfs/page-13.txt').read_text().splitlines():
 m=re.match(r'(.+?)\\s+(-?\\d+\\.\\d+)\\s+(\\d+\\.\\d+)\\s+(-?\\d+\\.\\d+)\\s+(\\d+\\.\\d+)\\s+(.+)"'$'"',line)
 if m:
  name=m[1];vals=list(map(float,m.group(2,3,4,5)));rows.append((name,vals))
print('Table 14 rows:',len(rows))
for label,rs in [('all',rows),('male',rows[:20]),('female',rows[20:])]:
 print(label,'mean single STS:',statistics.mean(v[0] for n,v in rs),'mean paired STS:',statistics.mean(v[2] for n,v in rs))
 print(label,'mean absolute single STS:',statistics.mean(abs(v[0]) for n,v in rs),'mean absolute paired STS:',statistics.mean(abs(v[2]) for n,v in rs))
rows2=[]
for line in Path('tmp/pdfs/page-15.txt').read_text().splitlines():
 m=re.match(r'(.+?)\\s+(minor|power)\\s+(-?\\d+\\.\\d+)\\s+(-?\\d+\\.\\d+)\\s+(-?\\d+\\.\\d+)"'$'"',line)
 if m:rows2.append((m[1],m[2],list(map(float,m.group(3,4,5)))))
print('Table 16 rows:',len(rows2))
for label,rs in [('all',rows2),('minor',[r for r in rows2 if r[1]=='minor']),('power',[r for r in rows2 if r[1]=='power'])]:
 print(label,'mean single STS:',statistics.mean(v[0] for n,t,v in rs),'mean paired STS:',statistics.mean(v[1] for n,t,v in rs))
print('Arithmetic errors Table 16:')
for n,t,v in rows2:
 if abs(v[2]-(v[1]-v[0]))>.02:print(n,t,v,'expected:',round(v[1]-v[0],2))
print('Top 5 paired Table14 means:',statistics.mean(sorted([v[2] for n,v in rows[:20]],reverse=True)[:5]),statistics.mean(sorted([v[2] for n,v in rows[20:]],reverse=True)[:5]))
PY"
